function measureTracked(ctx, text, unitSize, tracking) {
  if (!text) return 0;
  let total = 0;
  for (let i = 0; i < text.length; i++) {
    total += unitSize * 0.55;
    if (i < text.length - 1) total += tracking;
  }
  return total;
